/*
 * A111225  Numbers n such that 5*n + 8 is prime.
 * https://oeis.org/A111225
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   not stated
 * Range:     u8 n <= 53, u16 n <= 1000, u32 n <= 1000, u64 n <= 1000,
 *            u128 n <= 1000, big any n
 * Validated: standard, pass, 74 terms through n = 993 (2026-11-03)
 * Helpers:   is_prime_u64, mem
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Sequence: a(n) = the n-th integer k for which 5*k+8 is prime. */
/* The sequence is generated by searching successive integers and
   keeping those that satisfy the property. */

#include <stdint.h>
#include <stddef.h>
#include <stdbool.h>
#include <stdlib.h>
#include "../utils/is_prime_u64.h"
#include "../utils/mem.h"

/* helper to allocate an array of seq_t that works in both C and C++ */
static inline seq_t *seq_malloc(idx_t n)
{
#ifdef __cplusplus
    return mem_new(seq_t, n);
#else
    return (seq_t *)malloc(n * sizeof(seq_t));
#endif
}

static inline seq_t *seq_realloc(seq_t *p, idx_t n)
{
#ifdef __cplusplus
    return mem_resize(seq_t, p, n);
#else
    return (seq_t *)realloc(p, n * sizeof(seq_t));
#endif
}

/* Resize the cache array to at least new_cap elements.
   If the cache is NULL, allocate a new array. */
static void ensure_cache_size(size_t new_cap, seq_t **arr, size_t *cap)
{
    if (*cap >= new_cap)
        return;

    size_t n_cap = (*cap > 0) ? *cap * 2 : 16;
    while (n_cap < new_cap)
        n_cap <<= 1;

    seq_t *tmp = NULL;
    if (*arr == NULL)
        tmp = seq_malloc((idx_t)n_cap);
    else
        tmp = seq_realloc(*arr, (idx_t)n_cap);

    *arr = tmp;
    *cap = n_cap;
}

seq_t a(idx_t n)
{
    static seq_t *cache  = NULL;   /* stored values               */
    static size_t sz      = 0;     /* number of stored terms      */
    static size_t cap     = 0;     /* allocated capacity          */
    static idx_t  cand    = 1;     /* next integer to test        */

    if (n == 0)                     /* offset 0 is undefined       */
        return 0;

    /* Generate more terms until we have at least n terms. */
    while (sz < n)
    {
        uint64_t m = (uint64_t)cand;          /*  candidate as 64‑bit      */
        if (is_prime_u64(m * 5ULL + 8ULL))
        {
            ensure_cache_size(sz + 1, &cache, &cap);
            cache[sz++] = (seq_t)cand;        /* store the candidate      */
        }
        cand++;
    }

    return cache[n - 1];
}
